def normalized_language(value: str | None) -> str:
    value = (value or "pt").lower().split("-")[0]
    return value if value in LANGUAGES else "pt"


def translate(lang: str, key: str, **values: object) -> str:
    phrase = TEXT[key][LANGUAGES.index(normalized_language(lang))]
    return phrase.format(**values) if values else phrase


def frontend_text(lang: str) -> dict[str, str]:
    return {key[3:]: translate(lang, key) for key in TEXT if key.startswith("js_")}


