def result_label(lang: str, value: str) -> str:
    """Traduz somente valores conhecidos; conserva diagnósticos novos intactos."""
    key = _RESULT_LABEL_KEYS.get(value)
    return translate(lang, key) if key else value


_PITCH_NAMES = {
    "pt": {"Dó": "Dó", "Ré": "Ré", "Mi": "Mi", "Fá": "Fá", "Sol": "Sol", "Lá": "Lá", "Si": "Si"},
    "en": {"Dó": "C", "Ré": "D", "Mi": "E", "Fá": "F", "Sol": "G", "Lá": "A", "Si": "B"},
    "fr": {"Dó": "Do", "Ré": "Ré", "Mi": "Mi", "Fá": "Fa", "Sol": "Sol", "Lá": "La", "Si": "Si"},
    "es": {"Dó": "Do", "Ré": "Re", "Mi": "Mi", "Fá": "Fa", "Sol": "Sol", "Lá": "La", "Si": "Si"},
}
_MODE_NAMES = {"pt": ("maior", "menor"), "en": ("major", "minor"),
               "fr": ("majeur", "mineur"), "es": ("mayor", "menor")}


def display_key_name(lang: str, value: str | None) -> str:
    """Formata só nomes tonais canônicos; não altera a análise nem MusicXML."""
    if not value:
        return "—"
    match = re.fullmatch(r"(Dó|Ré|Mi|Fá|Sol|Lá|Si)([♭♯]?) (maior|menor)", value)
    if not match:
        return value
    language = normalized_language(lang)
    pitch, accidental, mode = match.groups()
    mode_name = _MODE_NAMES[language][0 if mode == "maior" else 1]
    return f"{_PITCH_NAMES[language][pitch]}{accidental} {mode_name}"
